import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import fs from 'fs'
import path from 'path'
import { execSync } from 'child_process'
import { PrismaClient } from '@prisma/client'

describe('corpus_source_state migration', () => {
  let prisma: PrismaClient
  let migrationPath: string

  beforeAll(() => {
    prisma = new PrismaClient()
    const migrationDir = path.join(process.cwd(), 'prisma/migrations')
    const migrations = fs.readdirSync(migrationDir)
    const seedMigration = migrations.find(m => m.includes('corpus_source_state_seed'))
    if (!seedMigration) {
      throw new Error('corpus_source_state_seed migration not found')
    }
    migrationPath = path.join(migrationDir, seedMigration, 'migration.sql')
  })

  afterAll(async () => {
    await prisma.$disconnect()
  })

  describe('migration file existence and structure', () => {
    it('should create migration file at prisma/migrations/<timestamp>_corpus_source_state_seed', () => {
      expect(fs.existsSync(migrationPath)).toBe(true)
    })

    it('migration.sql should be valid and non-empty', () => {
      const content = fs.readFileSync(migrationPath, 'utf-8')
      expect(content.length).toBeGreaterThan(0)
    })

    it('should contain CREATE TABLE statement', () => {
      const content = fs.readFileSync(migrationPath, 'utf-8').toUpperCase()
      expect(content).toMatch(/CREATE\s+TABLE/)
    })

    it('should use IF NOT EXISTS to prevent duplicate table creation', () => {
      const content = fs.readFileSync(migrationPath, 'utf-8').toUpperCase()
      expect(content).toMatch(/IF\s+NOT\s+EXISTS/)
    })
  })

  describe('table schema definition', () => {
    it('should include id column as primary key', () => {
      const content = fs.readFileSync(migrationPath, 'utf-8').toUpperCase()
      expect(content).toMatch(/\bid\b.*PRIMARY\s+KEY/)
    })

    it('should include name column as unique VARCHAR', () => {
      const content = fs.readFileSync(migrationPath, 'utf-8').toUpperCase()
      expect(content).toMatch(/name\b.*VARCHAR.*UNIQUE/)
    })

    it('should include earliest_target as DATETIME or TIMESTAMP', () => {
      const content = fs.readFileSync(migrationPath, 'utf-8').toUpperCase()
      expect(content).toMatch(/earliest_target\b.*(DATETIME|TIMESTAMP)/)
    })

    it('should include latest_target as DATETIME or TIMESTAMP', () => {
      const content = fs.readFileSync(migrationPath, 'utf-8').toUpperCase()
      expect(content).toMatch(/latest_target\b.*(DATETIME|TIMESTAMP)/)
    })

    it('should include coverage_pct as NUMERIC, DECIMAL, or similar', () => {
      const content = fs.readFileSync(migrationPath, 'utf-8').toUpperCase()
      expect(content).toMatch(/coverage_pct\b.*(NUMERIC|DECIMAL|FLOAT|DOUBLE)/)
    })

    it('should include created_at as DATETIME/TIMESTAMP with default', () => {
      const content = fs.readFileSync(migrationPath, 'utf-8').toUpperCase()
      expect(content).toMatch(/created_at\b.*(DATETIME|TIMESTAMP)/)
    })

    it('should include updated_at as DATETIME/TIMESTAMP with auto-update', () => {
      const content = fs.readFileSync(migrationPath, 'utf-8').toUpperCase()
      expect(content).toMatch(/updated_at\b.*(DATETIME|TIMESTAMP)/)
    })
  })

  describe('indexes', () => {
    it('should create index on coverage_pct column', () => {
      const content = fs.readFileSync(migrationPath, 'utf-8').toUpperCase()
      expect(content).toMatch(/CREATE\s+INDEX.*coverage_pct/)
    })
  })

  describe('seed data structure', () => {
    it('should include INSERT statements for data', () => {
      const content = fs.readFileSync(migrationPath, 'utf-8').toUpperCase()
      expect(content).toMatch(/INSERT\s+INTO/)
    })

    it('should populate exactly six source records', () => {
      const content = fs.readFileSync(migrationPath, 'utf-8')
      const insertMatches = content.match(/VALUES\s*\(/gi) || []
      expect(insertMatches.length).toBe(6)
    })

    it('should include historical depth metadata columns in INSERT', () => {
      const content = fs.readFileSync(migrationPath, 'utf-8').toUpperCase()
      expect(content).toMatch(/name.*earliest_target.*latest_target.*coverage_pct/)
    })
  })

  describe('database table verification', () => {
    it('table corpus_source_state should exist after migration', async () => {
      const tables = await prisma.$queryRawUnsafe<{ TABLE_NAME: string }[]>(
        "SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'corpus_source_state'"
      )
      expect(tables.length).toBe(1)
    })

    it('should have six records after seeding', async () => {
      const count = await prisma.corpusSourceState.count()
      expect(count).toBe(6)
    })

    it('should be able to query all records with required fields', async () => {
      const sources = await prisma.corpusSourceState.findMany()
      expect(sources.length).toBe(6)
      sources.forEach(source => {
        expect(source.id).toBeDefined()
        expect(source.name).toBeDefined()
        expect(source.earliestTarget).toBeDefined()
        expect(source.latestTarget).toBeDefined()
        expect(source.coveragePct).toBeDefined()
        expect(source.createdAt).toBeDefined()
        expect(source.updatedAt).toBeDefined()
      })
    })
  })

  describe('data integrity constraints', () => {
    it('all source names should be unique', async () => {
      const sources = await prisma.corpusSourceState.findMany()
      const names = sources.map(s => s.name)
      const uniqueNames = new Set(names)
      expect(uniqueNames.size).toBe(6)
    })

    it('coverage_pct should be numeric and between 0 and 100', async () => {
      const sources = await prisma.corpusSourceState.findMany()
      sources.forEach(source => {
        expect(typeof source.coveragePct).toBe('number')
        expect(source.coveragePct).toBeGreaterThanOrEqual(0)
        expect(source.coveragePct).toBeLessThanOrEqual(100)
      })
    })

    it('latest_target should be >= earliest_target for all records', async () => {
      const sources = await prisma.corpusSourceState.findMany()
      sources.forEach(source => {
        expect(source.latestTarget.getTime()).toBeGreaterThanOrEqual(
          source.earliestTarget.getTime()
        )
      })
    })

    it('updated_at should be >= created_at for all records', async () => {
      const sources = await prisma.corpusSourceState.findMany()
      sources.forEach(source => {
        expect(source.updatedAt.getTime()).toBeGreaterThanOrEqual(
          source.createdAt.getTime()
        )
      })
    })

    it('attempting to insert duplicate name should fail', async () => {
      const firstSource = await prisma.corpusSourceState.findFirst()
      await expect(
        prisma.corpusSourceState.create({
          data: {
            name: firstSource!.name,
            earliestTarget: new Date('2024-01-01'),
            latestTarget: new Date('2024-12-31'),
            coveragePct: 50.0
          }
        })
      ).rejects.toThrow()
    })
  })

  describe('index functionality', () => {
    it('coverage_pct index should exist and be queryable', async () => {
      const indexInfo = await prisma.$queryRawUnsafe<{ Key_name: string }[]>(
        "SHOW INDEX FROM corpus_source_state WHERE Column_name = 'coverage_pct'"
      )
      expect(indexInfo.length).toBeGreaterThan(0)
    })

    it('should efficiently query by coverage_pct using index', async () => {
      const result = await prisma.corpusSourceState.findMany({
        where: {
          coveragePct: {
            gte: 50
          }
        }
      })
      expect(Array.isArray(result)).toBe(true)
    })
  })

  describe('seed data validation', () => {
    it('should have six distinct source names', async () => {
      const sources = await prisma.corpusSourceState.findMany({
        orderBy: { name: 'asc' }
      })
      const expectedNames = ['api', 'documentation', 'examples', 'github', 'tests', 'tutorials'].sort()
      const actualNames = sources.map(s => s.name).sort()
      expect(actualNames).toEqual(expectedNames)
    })

    it('each source should have a non-null earliest_target', async () => {
      const sources = await prisma.corpusSourceState.findMany()
      sources.forEach(source => {
        expect(source.earliestTarget).not.toBeNull()
        expect(source.earliestTarget instanceof Date).toBe(true)
      })
    })

    it('each source should have a non-null latest_target', async () => {
      const sources = await prisma.corpusSourceState.findMany()
      sources.forEach(source => {
        expect(source.latestTarget).not.toBeNull()
        expect(source.latestTarget instanceof Date).toBe(true)
      })
    })

    it('coverage values should represent realistic coverage percentages', async () => {
      const sources = await prisma.corpusSourceState.findMany()
      const coverageValues = sources.map(s => s.coveragePct).sort((a, b) => a - b)
      expect(coverageValues[0]).toBeLessThan(coverageValues[coverageValues.length - 1])
      expect(Math.min(...coverageValues)).toBeGreaterThanOrEqual(0)
      expect(Math.max(...coverageValues)).toBeLessThanOrEqual(100)
    })
  })
})
